def getrand():
    n = randint(1,3)
    m = randint(0,5)
    s = []
    for i in range(m):
        s.append([randint(1,n),randint(0,9)])
    s.sort()
    print([n,m])
    print(s)
    return n,m,s

def getval():
    n,m = map(int,input().split())
    s = [list(map(int,input().split())) for i in range(m)]
    return n,m,s

