    n,m = map(int,input().split())
    s = [list(map(int,input().split())) for i in range(m)]
    return n,m,s

def main(n,m,s):
    #Initiate
    temp = [-1 for i in range(n)]
    ans = ""
    flag = True
    #Exceptions: contains dup or ([1,0] and n>1)
    if [1,0] in s and n>1:
        flag = False
    for i in s:
        if not temp[i[0]-1] in [-1,i[1]]:
            flag = False
            break
        temp[i[0]-1] = i[1]
    if flag:
