            if m==0:
                ans = "0"
            else:
                ans = str(temp[0])
        else:
            if temp[0]==-1:
                temp[0] = 1
            for i in range(0,n):
                if temp[i]==-1:
                    temp[i] = 0
            for i in temp:
                ans += str(i)
    else:
        ans = "-1"
    print(ans)


